import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { createDatabase } from "./client.js";

// SQL migration files generated by drizzle-kit (packages/db/drizzle).
const migrationsFolder = fileURLToPath(new URL("../drizzle", import.meta.url));

/** Applies every pending migration. Returns false if there are no migrations yet. */
export async function runMigrations(databaseUrl: string): Promise<boolean> {
  if (!existsSync(`${migrationsFolder}/meta/_journal.json`)) return false;

  const { db, close } = createDatabase(databaseUrl, { maxConnections: 1 });
  try {
    await migrate(db, { migrationsFolder });
    return true;
  } finally {
    await close();
  }
}
